(window.KOTOBA_HK=window.KOTOBA_HK||{})[33]={"n":33,"S":[{"id":"l33a","ti":[[["忠犬","ちゅうけん"],["ハチ公","はちこう"]]],"tt":{"az":"Sadiq it Haçiko","en":"Hachiko, the Loyal Dog","ru":"Верный пёс Хатико"},"P":[{"t":[[["むかし","むかし"],["、"],["東京","とうきょう"],["に","に"]],[["ハチ","ハチ"],["と","と"],["いう","いう","いう",5]],[["犬","いぬ"],["が","が"]],[["いました","いました","いる",2],["。"],["ハチ","ハチ"],["は","は"]],[["大学","だいがく"],["の","の"]],[["先生","せんせい"],["に","に"]],[["飼われて","かわれて","飼われて",65]],[["いました","いました","いる",2],["。"],["先生","せんせい"],["は","は"]],[["ハチ","ハチ"],["を","を"]],[["とても","とても"]],[["かわいがって","かわいがって","かわいがって",3]],[["いました","いました","いる",2],["。"],["ハチ","ハチ"],["も","も"]],[["先生","せんせい"],["が","が"]],[["大好き","だいすき"],["でした","でした","です",9],["。"]]],"tr":{"az":"Keçmişdə Tokioda Haçi adlı bir it yaşayırdı. Haçini universitet müəllimi saxlayırdı. Müəllim Haçini çox sevirdi. Haçi də müəllimini çox sevirdi.","en":"Long ago, there was a dog named Hachi in Tokyo. Hachi was cared for by a university professor. The professor loved Hachi very much. Hachi loved his master, too.","ru":"Давным-давно в Токио жил пёс по имени Хати. О нём заботился профессор университета. Профессор очень любил Хати. Хати тоже очень любил своего хозяина."}},{"t":[[["毎朝","まいあさ"],["、"],["先生","せんせい"],["は","は"]],[["電車","でんしゃ"],["で","で"]],[["大学","だいがく"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["ハチ","ハチ"],["は","は"]],[["先生","せんせい"],["と","と"]],[["いっしょ","いっしょ"],["に","に"]],[["渋谷","しぶや"],["駅","えき"],["まで","まで"]],[["歩きました","あるきました","歩く",2],["。"],["駅","えき"],["で","で"]],[["先生","せんせい"],["に","に"]],[["頭","あたま"],["を","を"]],[["なでられる","なでられる","なでる",63],["と","と"],["、"],["うれし","うれし","うれしい"],["そうに","そうに","そう",8]],[["しっぽ","しっぽ"],["を","を"]],[["振りました","ふりました","振る",2],["。"],["夕方","ゆうがた"],["に","に"],["は","は"]],[["また","また"]],[["駅","えき"],["へ","へ"]],[["迎え","むかえ","迎える",10],["に","に"]],[["行きました","いきました","行く",2],["。"]]],"tr":{"az":"Müəllim hər səhər qatarla universitetə gedirdi. Haçi müəllimlə birlikdə Şibuya stansiyasına qədər gedirdi. Stansiyada müəllim onun başını sığallayanda Haçi sevinclə quyruğunu bulayırdı. Axşam isə müəllimini qarşılamaq üçün yenidən stansiyaya gedirdi.","en":"Every morning, the professor took the train to the university. Hachi walked with him to Shibuya Station. When the professor patted his head, Hachi wagged his tail happily. In the evening, he returned to the station to meet him.","ru":"Каждое утро профессор ездил в университет на поезде. Хати провожал его до станции Сибуя. Когда профессор гладил его по голове, Хати радостно вилял хвостом. Вечером он снова приходил на станцию встречать хозяина."}},{"t":[[["ある日","あるひ"],["、"],["先生","せんせい"],["は","は"]],[["大学","だいがく"],["で","で"]],[["急","きゅう"],["に","に"]],[["倒れました","たおれました","倒れました",2],["。"],["先生","せんせい"],["は","は"]],[["その","その"],["まま","まま"]],[["亡くなって","なくなって","亡くなって",3]],[["しまいました","しまいました","しまいました",2],["。"],["でも","でも"],["、"],["ハチ","ハチ"],["は","は"]],[["その","その"],["こと","こと"],["を","を"]],[["知りませんでした","しりませんでした","知る",4],["。"],["いつ","いつ"],["も","も"],["の","の"]],[["時間","じかん"],["に","に"]],[["駅","えき"],["へ","へ"]],[["行って","いって","行く",3],["、"],["先生","せんせい"],["を","を"]],[["待ちました","まちました","待つ",2],["。"]]],"tr":{"az":"Bir gün müəllim universitetdə qəflətən yıxıldı. Təəssüf ki, o, vəfat etdi. Amma Haçi bundan xəbərsiz idi. Həmişəki vaxtda stansiyaya gedib müəllimini gözlədi.","en":"One day, the professor suddenly collapsed at the university. Sadly, he passed away. But Hachi did not know what had happened. At the usual time, he went to the station and waited for his master.","ru":"Однажды профессор внезапно упал в университете. К сожалению, он скончался. Но Хати ничего об этом не знал. В привычное время он пришёл на станцию и стал ждать хозяина."}},{"t":[[["夜","よる"],["に","に"]],[["なっても","なっても","なる",34],["、"],["先生","せんせい"],["は","は"]],[["帰って","かえって","帰る",3]],[["きませんでした","きませんでした","くる",4],["。"],["ハチ","ハチ"],["は","は"]],[["駅","えき"],["の","の"]],[["人","ひと"],["に","に"]],[["心配","しんぱい"],["されました","されました","する",27],["。"],["近く","ちかく"],["の","の"]],[["店","みせ"],["の","の"]],[["人","ひと"],["に","に"]],[["水","みず"],["を","を"]],[["もらいました","もらいました","もらう",2],["が","が"],["、"],["駅","えき"],["を","を"]],[["離れよう","はなれよう","離れよう",7],["と","と"]],[["しませんでした","しませんでした","する",4],["。"],["次","つぎ"],["の","の"],["日","ひ"],["も","も"],["、"],["その","その"],["次","つぎ"],["の","の"],["日","ひ"],["も","も"],["、"],["先生","せんせい"],["を","を"]],[["待ちました","まちました","待つ",2],["。"]]],"tr":{"az":"Gecə düşsə də, müəllim qayıtmadı. Stansiya işçiləri Haçiyə görə narahat oldular. Yaxınlıqdakı mağazanın işçisi ona su verdi, amma Haçi stansiyadan ayrılmaq istəmədi. Ertəsi gün də, ondan sonrakı gün də müəllimini gözlədi.","en":"Even when night fell, the professor did not return. The station workers worried about Hachi. Someone from a nearby shop gave him water, but he refused to leave the station. He waited the next day and the day after that, too.","ru":"Даже когда наступила ночь, профессор не вернулся. Работники станции беспокоились о Хати. Работник соседнего магазина дал ему воды, но Хати не хотел уходить со станции. Он ждал и на следующий день, и через день."}},{"t":[[["初め","はじめ"],["は","は"]],[["ハチ","ハチ"],["を","を"]],[["知らない","しらない","知る",19]],[["人","ひと"],["も","も"]],[["いました","いました","いる",2],["。"],["道","みち"],["を","を"]],[["歩いて","あるいて","歩く",3]],[["いる","いる","いる",5],["とき","とき"],["、"],["子ども","こども"],["に","に"]],[["しっぽ","しっぽ"],["を","を"]],[["引っぱられた","ひっぱられた","引っぱられた",55]],[["こと","こと"],["も","も"]],[["ありました","ありました","ある",2],["。"],["でも","でも"],["、"],["ハチ","ハチ"],["は","は"]],[["怒りませんでした","おこりませんでした","怒る",4],["。"],["ただ","ただ"]],[["静かに","しずかに","静か",8]],[["駅","えき"],["の","の"]],[["前","まえ"],["に","に"]],[["座って","すわって","座る",3]],[["いました","いました","いる",2],["。"]]],"tr":{"az":"Əvvəlcə Haçini tanımayan insanlar da var idi. Bir dəfə yolda gedərkən bir uşaq onun quyruğunu dartmışdı. Amma Haçi hirslənmədi. O, sadəcə stansiyanın qarşısında sakitcə otururdu.","en":"At first, some people did not know Hachi. Once, while he was walking along the street, a child pulled his tail. But Hachi did not get angry. He simply sat quietly in front of the station.","ru":"Поначалу некоторые люди не знали Хати. Однажды, когда он шёл по улице, ребёнок дёрнул его за хвост. Но Хати не рассердился. Он просто тихо сидел перед станцией."}},{"t":[[["やがて","やがて"],["、"],["ハチ","ハチ"],["の","の"]],[["話","はなし"],["が","が"]],[["新聞","しんぶん"],["に","に"]],[["書かれました","かかれました","書く",27],["。"],["ハチ","ハチ"],["は","は"]],[["日本中","にほんなか"],["の","の"]],[["人","ひと"],["に","に"]],[["知られる","しられる","知る",92]],[["ように","ように","よう",8]],[["なりました","なりました","なる",2],["。"],["毎日","まいにち"],["、"],["多く","おおく"],["の","の"]],[["人","ひと"],["に","に"]],[["声","こえ"],["を","を"]],[["かけられ","かけられ","かける",63],["、"],["食べ物","たべもの"],["を","を"]],[["もらいました","もらいました","もらう",2],["。"],["「"],["今日","きょう"],["も","も"]],[["先生","せんせい"],["を","を"]],[["待って","まって","待つ",3]],[["いる","いる","いる",5],["ん","ん"],["だ","だ","です"],["ね","ね"],["」"],["と","と"]],[["言われました","いわれました","言う",27],["。"]]],"tr":{"az":"Bir müddət sonra Haçinin hekayəsi qəzetdə yazıldı. Haçi bütün Yaponiyada tanınmağa başladı. Hər gün çoxlu insan onunla danışır və ona yemək verirdi. İnsanlar «Bu gün də müəllimini gözləyirsən, eləmi?» deyirdilər.","en":"Before long, Hachi's story was written about in a newspaper. He became known throughout Japan. Every day, many people spoke to him and gave him food. They said, “You're waiting for your master again today, aren't you?”","ru":"Вскоре историю Хати напечатали в газете. О нём узнали по всей Японии. Каждый день многие люди обращались к нему и давали еду. Они говорили: «Ты и сегодня ждёшь своего хозяина, правда?»"}},{"t":[[["それから","それから"]],[["長い","ながい"]],[["年月","としつき"],["が","が"]],[["過ぎました","すぎました","過ぎました",2],["。"],["ハチ","ハチ"],["は","は"]],[["年","とし"],["を","を"]],[["取って","とって","取る",3],["、"],["歩く","あるく","歩く",5],["の","の"],["が","が"]],[["遅く","おそく","遅い"]],[["なりました","なりました","なる",2],["。"],["それ","それ"],["でも","でも"]],[["毎日","まいにち"],["、"],["駅","えき"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["ハチ","ハチ"],["の","の"]],[["やさしい","やさしい"]],[["心","こころ"],["は","は"]],[["多く","おおく"],["の","の"]],[["人","ひと"],["に","に"]],[["ほめられました","ほめられました","ほめられました",64],["。"]]],"tr":{"az":"Beləcə uzun illər keçdi. Haçi qocaldı və daha yavaş yeriməyə başladı. Buna baxmayaraq, hər gün stansiyaya gedirdi. Çoxlu insan Haçinin sədaqətini və mehriban qəlbini tərifləyirdi.","en":"Many years passed. Hachi grew old and began walking more slowly. Even so, he went to the station every day. His loving and loyal heart was praised by many people.","ru":"Прошло много лет. Хати состарился и стал ходить медленнее. Несмотря на это, он каждый день приходил на станцию. Многие люди восхищались его добрым и преданным сердцем."}},{"t":[[["とうとう","とうとう"]],[["ハチ","ハチ"],["も","も"]],[["亡くなりました","なくなりました","亡くなりました",2],["。"],["その","その"],["後","あと"],["、"],["ハチ","ハチ"],["の","の"]],[["像","ぞう"],["が","が"]],[["人々","ひとびと"],["に","に"]],[["よって","よって","よって",3]],[["駅","えき"],["の","の"]],[["前","まえ"],["に","に"]],[["建てられました","たてられました","建てられました",64],["。"],["今","いま"],["も","も"]],[["その","その"]],[["像","ぞう"],["は","は"]],[["多く","おおく"],["の","の"]],[["人","ひと"],["に","に"]],[["愛されて","あいされて","愛されて",65]],[["います","います","いる",11],["。"],["先生","せんせい"],["を","を"]],[["待って","まって","待つ",3]],[["いた","いた","いる",0]],[["ハチ","ハチ"],["は","は"],["、"],["今","いま"],["で","で"],["は","は"]],[["友だち","ともだち"],["を","を"]],[["待つ","まつ","待つ",5]],[["人たち","ひとたち"],["の","の"]],[["そば","そば"],["に","に"]],[["います","います","いる",11],["。"]]],"tr":{"az":"Nəhayət, Haçi də vəfat etdi. Sonra insanlar stansiyanın qarşısında onun heykəlini ucaltdılar. Bu gün də həmin heykəl çoxlu insan tərəfindən sevilir. Bir vaxtlar müəllimini gözləyən Haçi indi dostlarını gözləyən insanların yanındadır.","en":"At last, Hachi also passed away. Afterward, people built a statue of him in front of the station. Even today, the statue is loved by many people. Hachi, who once waited for his master, now stands beside people waiting for their friends.","ru":"В конце концов Хати тоже умер. Позже люди установили ему памятник перед станцией. И сегодня этот памятник любим многими. Хати, который когда-то ждал своего хозяина, теперь находится рядом с людьми, ожидающими своих друзей."}}]},{"id":"l33b","ti":[[["ロボット","ロボット"],["の","の"],["星丸","ほしまる"],["と","と"],["学校","がっこう"],["の","の"],["ひみつ","ひみつ"]]],"tt":{"az":"Robot Hoşimaru və məktəbin sirri","en":"Hoshimaru the Robot and the School Secret","ru":"Робот Хосимару и школьная тайна"},"P":[{"t":[[["ある","ある","ある(連体詞)"]],[["町","まち"],["に","に"],["、"],["星丸","ほしまる"],["と","と"],["いう","いう","いう",5]],[["小さな","ちいさな"]],[["ロボット","ロボット"],["が","が"]],[["いました","いました","いる",2],["。"],["星丸","ほしまる"],["は","は"]],[["町","まち"],["の","の"]],[["博士","はかせ"],["に","に"]],[["よって","よって","よって",3]],[["作られました","つくられました","作る",27],["。"],["ある","ある","ある(連体詞)"]],[["春","はる"],["の","の"],["日","ひ"],["、"],["星丸","ほしまる"],["は","は"]],[["人間","にんげん"],["の","の"]],[["学校","がっこう"],["に","に"]],[["入れられました","いれられました","入れる",64],["。"],["星丸","ほしまる"],["は","は"]],[["友だち","ともだち"],["が","が"]],[["できる","できる","できる",5],["か","か"]],[["心配","しんぱい"],["でした","でした","です",9],["。"]]],"tr":{"az":"Bir şəhərdə Hoşimaru adlı balaca robot yaşayırdı. Hoşimaru şəhərdəki bir alim tərəfindən hazırlanmışdı. Bir yaz günü onu insanların oxuduğu məktəbə yazdırdılar. Hoşimaru dost tapa biləcəyindən narahat idi.","en":"In a town, there was a little robot named Hoshimaru. He had been created by a scientist in the town. One spring day, Hoshimaru was enrolled in a school for humans. He worried about whether he could make friends.","ru":"В одном городе жил маленький робот по имени Хосимару. Его создал местный учёный. Однажды весной Хосимару записали в обычную школу для детей. Он беспокоился, сможет ли найти друзей."}},{"t":[[["学校","がっこう"],["の","の"]],[["初日","しょにち"],["、"],["星丸","ほしまる"],["は","は"]],[["先生","せんせい"],["に","に"]],[["名前","なまえ"],["を","を"]],[["呼ばれました","よばれました","呼ぶ",27],["。"],["立ち上がる","たちあがる","立ち上がる",5],["と","と"],["、"],["頭","あたま"],["から","から"]],[["小さな","ちいさな"]],[["光","ひかり"],["が","が"]],[["出ました","でました","出る",2],["。"],["クラス","クラス"],["の","の"]],[["子どもたち","こどもたち"],["に","に"]],[["笑われて","わらわれて","笑う",65],["、"],["顔","かお"],["が","が"]],[["赤く","あかく","赤い"]],[["光りました","ひかりました","光る",2],["。"],["でも","でも"],["、"],["先生","せんせい"],["に","に"],["は","は"],["「"],["元気","げんき"],["で","で"]],[["いい","いい"],["です","です"],["ね","ね"],["」"],["と","と"]],[["ほめられました","ほめられました","ほめられました",64],["。"]]],"tr":{"az":"Məktəbin ilk günü müəllim Hoşimarunun adını çağırdı. O ayağa qalxanda başından balaca bir işıq çıxdı. Sinifdəki uşaqlar ona güldülər və robotun üzü qırmızı işıq saçdı. Amma müəllim onu «Nə gözəl enerjin var!» deyərək təriflədi.","en":"On his first day at school, the teacher called Hoshimaru's name. When he stood up, a small light shone from his head. The children laughed at him, and his face glowed red. But the teacher praised him, saying, “What wonderful energy!”","ru":"В первый школьный день учитель назвал имя Хосимару. Когда тот встал, из его головы засиял маленький огонёк. Дети засмеялись, и лицо робота засветилось красным. Но учитель похвалил его: «Какой ты энергичный!»"}},{"t":[[["次","つぎ"],["の","の"],["日","ひ"],["、"],["算数","さんすう"],["の","の"]],[["時間","じかん"],["に","に"]],[["星丸","ほしまる"],["は","は"]],[["難しい","むずかしい"]],[["問題","もんだい"],["を","を"]],[["すぐ","すぐ"]],[["解きました","ときました","解きました",2],["。"],["先生","せんせい"],["に","に"],["「"],["すばらしい","すばらしい"],["」"],["と","と"]],[["ほめられました","ほめられました","ほめられました",64],["。"],["友だち","ともだち"],["に","に"],["も","も"],["「"],["頭","あたま"],["が","が"]],[["いい","いい"],["ね","ね"],["」"],["と","と"]],[["言われました","いわれました","言う",27],["。"],["星丸","ほしまる"],["の","の"]],[["胸","むね"],["の","の"]],[["星","ほし"],["は","は"]],[["金色","きんいろ"],["に","に"]],[["光りました","ひかりました","光る",2],["。"]]],"tr":{"az":"Ertəsi gün riyaziyyat dərsində Hoşimaru çətin məsələni dərhal həll etdi. Müəllim onu «Əladır!» deyərək təriflədi. Dostları da «Çox ağıllısan!» dedilər. Hoşimarunun sinəsindəki ulduz qızılı rəngdə parladı.","en":"The next day, during math class, Hoshimaru solved a difficult problem immediately. The teacher praised him, saying, “Excellent!” His classmates also said, “You're really smart!” The star on Hoshimaru's chest glowed gold.","ru":"На следующий день на уроке математики Хосимару сразу решил сложную задачу. Учитель похвалил его: «Превосходно!» Одноклассники тоже сказали: «Какой ты умный!» Звезда на груди Хосимару засияла золотым светом."}},{"t":[[["しかし","しかし"],["、"],["昼休み","ひるやすみ"],["に","に"]],[["大きな","おおきな"]],[["失敗","しっぱい"],["を","を"]],[["しました","しました","する",2],["。"],["友だち","ともだち"],["を","を"]],[["助けよう","たすけよう","助ける",7],["と","と"],["して","して","する",3],["、"],["教室","きょうしつ"],["に","に"]],[["水","みず"],["を","を"]],[["まいて","まいて"]],[["しまった","しまった","しまった",0],["の","の"],["です","です"],["。"],["星丸","ほしまる"],["は","は"]],[["先生","せんせい"],["に","に"]],[["強く","つよく","強い"]],[["しかられました","しかられました","しかられました",27],["。"],["友だち","ともだち"],["に","に"],["は","は"]],[["ノート","ノート"],["を","を"]],[["ぬらされて","ぬらされて","ぬらされて",65]],[["悲しむ","かなしむ","悲しむ",5]],[["子","こ"],["も","も"]],[["いました","いました","いる",2],["。"]]],"tr":{"az":"Amma nahar fasiləsində böyük bir səhv etdi. Dostuna kömək etmək istəyərkən sinfə su püskürtdü. Müəllim onu ciddi şəkildə danladı. Bəzi uşaqların dəftərləri islanmışdı və onlar çox kədərlənmişdilər.","en":"However, during lunch break, he made a big mistake. While trying to help a friend, he sprayed water all over the classroom. The teacher scolded him severely. Some children were upset because their notebooks had been soaked.","ru":"Однако во время обеденного перерыва он совершил большую ошибку. Пытаясь помочь другу, он разбрызгал воду по всему классу. Учитель строго отругал его. Некоторые дети расстроились, потому что их тетради промокли."}},{"t":[[["星丸","ほしまる"],["は","は"]],[["自分","じぶん"],["の","の"]],[["席","せき"],["で","で"]],[["小さく","ちいさく","小さい"]],[["なって","なって","なる",3]],[["いました","いました","いる",2],["。"],["隣","となり"],["の","の"]],[["ミナ","ミナ"],["に","に"],["「"],["どう","どう"],["した","した","する",0],["の","の"],["」"],["と","と"]],[["聞かれました","きかれました","聞く",27],["。"],["星丸","ほしまる"],["は","は"],["「"],["ぼく","ぼく"],["は","は"]],[["役","やく"],["に","に"]],[["立たない","たたない","立つ",19]],[["ロボット","ロボット"],["です","です"],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"],["ミナ","ミナ"],["は","は"]],[["星丸","ほしまる"],["の","の"]],[["手","て"],["を","を"]],[["握って","にぎって","握る",3],["、"],["「"],["そんな","そんな"],["こと","こと"]],[["ない","ない"],["よ","よ"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Hoşimaru öz yerində büzüşüb oturmuşdu. Yanında oturan Mina ondan «Nə olub?» deyə soruşdu. Hoşimaru «Mən heç bir işə yaramayan robotam» cavabını verdi. Mina onun əlini tutub «Elə deyil» dedi.","en":"Hoshimaru sat quietly at his desk, trying to make himself small. Mina, who sat beside him, asked, “What's wrong?” Hoshimaru answered, “I'm a useless robot.” Mina held his hand and said, “That's not true.”","ru":"Хосимару сидел за партой, съёжившись. Сидевшая рядом Мина спросила: «Что случилось?» Хосимару ответил: «Я бесполезный робот». Мина взяла его за руку и сказала: «Это неправда»."}},{"t":[[["その","その"],["日","ひ"],["の","の"]],[["放課後","ほうかあと"],["、"],["学校","がっこう"],["の","の"]],[["大きな","おおきな"]],[["時計","とけい"],["が","が"]],[["止まりました","とまりました","止まる",2],["。"],["時計","とけい"],["は","は"]],[["百年","ひゃくねん"],["前","まえ"],["に","に"]],[["作られた","つくられた","作る",55]],[["大切な","たいせつな","大切",1]],[["もの","もの"],["でした","でした","です",9],["。"],["先生たち","せんせいたち"],["は","は"]],[["困って","こまって","困る",3]],[["いました","いました","いる",2],["。"],["星丸","ほしまる"],["は","は"]],[["ミナ","ミナ"],["に","に"]],[["背中","せなか"],["を","を"]],[["押されて","おされて","押す",65],["、"],["時計","とけい"],["の","の"]],[["ところ","ところ"],["へ","へ"]],[["行きました","いきました","行く",2],["。"]]],"tr":{"az":"Həmin gün dərsdən sonra məktəbin böyük saatı dayandı. Bu, yüz il əvvəl hazırlanmış qiymətli bir saat idi. Müəllimlər nə edəcəklərini bilmirdilər. Mina Hoşimarunu cəsarətləndirdi və o, saatın yanına getdi.","en":"After school that day, the school's big clock stopped. It was a precious clock made a hundred years earlier. The teachers did not know what to do. Encouraged by Mina, Hoshimaru went over to the clock.","ru":"После уроков большие школьные часы остановились. Это были ценные часы, сделанные сто лет назад. Учителя не знали, что делать. Мина подбодрила Хосимару, и он подошёл к часам."}},{"t":[[["星丸","ほしまる"],["は","は"]],[["時計","とけい"],["の","の"]],[["中","なか"],["を","を"]],[["調べました","しらべました","調べる",2],["。"],["小さな","ちいさな"]],[["ねじ","ねじ"],["が","が"]],[["一つ","ひとつ"]],[["外れて","はずれて","外れて",3]],[["いました","いました","いる",2],["。"],["星丸","ほしまる"],["は","は"]],[["指","ゆび"],["で","で"]],[["ねじ","ねじ"],["を","を"]],[["直しました","なおしました","直しました",2],["。"],["する","する","する",5],["と","と"],["、"],["時計","とけい"],["が","が"]],[["動き","うごき","動く",10],["出し","だし","出す",10],["、"],["学校中","がっこうなか"],["に","に"]],[["きれいな","きれいな","きれい",1]],[["音","おと"],["が","が"]],[["響きました","ひびきました","響きました",2],["。"]]],"tr":{"az":"Hoşimaru saatın içini yoxladı. Balaca bir vint yerindən çıxmışdı. O, barmağı ilə vinti yerinə taxdı. Elə bu anda saat yenidən işləməyə başladı və bütün məktəbdə gözəl zəng səsi eşidildi.","en":"Hoshimaru examined the inside of the clock. One small screw had come loose. He fixed the screw with his finger. Then the clock started moving, and a beautiful chime rang throughout the school.","ru":"Хосимару осмотрел часы изнутри. Один маленький винтик выпал со своего места. Он поправил винтик пальцем. Часы снова пошли, и по всей школе раздался красивый звон."}},{"t":[[["星丸","ほしまる"],["は","は"]],[["先生","せんせい"],["に","に"],["も","も"]],[["友だち","ともだち"],["に","に"],["も","も"]],[["ほめられました","ほめられました","ほめられました",64],["。"],["先生","せんせい"],["は","は"],["「"],["今日","きょう"],["は","は"]],[["よく","よく"]],[["がんばりました","がんばりました","がんばりました",2],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["星丸","ほしまる"],["は","は"]],[["うれしくて","うれしくて","うれしい",3],["、"],["頭","あたま"],["から","から"]],[["七色","なないろ"],["の","の"]],[["光","ひかり"],["を","を"]],[["出しました","だしました","出す",2],["。"],["みんな","みんな"],["に","に"]],[["また","また"]],[["笑われました","わらわれました","笑う",27],["が","が"],["、"],["今度","こんど"],["は","は"]],[["星丸","ほしまる"],["も","も"]],[["いっしょ","いっしょ"],["に","に"]],[["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Hoşimaru həm müəllim, həm də dostları tərəfindən tərifləndi. Müəllim «Bu gün çox yaxşı çalışdın» dedi. Hoşimaru sevincindən başından yeddi rəngli işıq saçdı. Hamı yenə güldü, amma bu dəfə Hoşimaru da onlarla birlikdə güldü.","en":"Hoshimaru was praised by both the teacher and his friends. The teacher said, “You worked very hard today.” Hoshimaru was so happy that rainbow-colored light shone from his head. Everyone laughed again, but this time Hoshimaru laughed with them.","ru":"Хосимару похвалили и учитель, и друзья. Учитель сказал: «Сегодня ты очень постарался». От радости из головы Хосимару засиял радужный свет. Все снова засмеялись, но на этот раз Хосимару смеялся вместе с ними."}}]},{"id":"l33c","ti":[[["消えた","きえた","消える",0],["お弁当","おべんとう"],["と","と"],["小さな","ちいさな"],["名探偵","めいたんてい"]]],"tt":{"az":"Yoxa çıxan bento və balaca xəfiyyə","en":"The Missing Lunch Box and the Little Detective","ru":"Пропавший обед и маленький сыщик"},"P":[{"t":[[["ある","ある","ある(連体詞)"]],[["町","まち"],["に","に"],["、"],["ユイ","ユイ"],["と","と"],["いう","いう","いう",5]],[["女の子","おんなのこ"],["が","が"]],[["いました","いました","いる",2],["。"],["ユイ","ユイ"],["は","は"]],[["毎朝","まいあさ"],["、"],["お母さん","おかあさん"],["に","に"]],[["お弁当","おべんとう"],["を","を"]],[["作って","つくって","作る",3]],[["もらいました","もらいました","もらう",2],["。"],["お弁当","おべんとう"],["に","に"],["は","は"]],[["いつ","いつ"],["も","も"]],[["小さな","ちいさな"]],[["卵焼き","たまごやき"],["が","が"]],[["入って","はいって","入る",3]],[["いました","いました","いる",2],["。"],["ユイ","ユイ"],["は","は"]],[["その","その"]],[["卵焼き","たまごやき"],["が","が"]],[["大好き","だいすき"],["でした","でした","です",9],["。"]]],"tr":{"az":"Bir şəhərdə Yui adlı bir qız yaşayırdı. Hər səhər anası ona bento hazırlayırdı. Yemək qutusunda həmişə balaca bir yumurta ruleti olurdu. Yui həmin yumurta ruletini çox sevirdi.","en":"In a town, there was a girl named Yui. Every morning, her mother made a lunch box for her. There was always a small rolled omelet inside. Yui loved that omelet very much.","ru":"В одном городе жила девочка по имени Юи. Каждое утро мама готовила ей обед в коробочке. Внутри всегда был маленький яичный рулет. Юи очень любила этот рулет."}},{"t":[[["ある日","あるひ"],["、"],["ユイ","ユイ"],["は","は"]],[["学校","がっこう"],["で","で"]],[["お弁当","おべんとう"],["の","の"]],[["ふた","ふた"],["を","を"]],[["開けました","あけました","開ける",2],["。"],["ところ","ところ"],["が","が"],["、"],["卵焼き","たまごやき"],["が","が"]],[["ありませんでした","ありませんでした","ある",4],["。"],["ユイ","ユイ"],["は","は"]],[["びっくり","びっくり"]],[["しました","しました","する",2],["。"],["「"],["だれ","だれ"],["か","か"],["に","に"]],[["食べられた","たべられた","食べる",98],["の","の"],["か","か"],["な","な"],["」"],["と","と"]],[["思いました","おもいました","思う",2],["。"],["そこ","そこ"],["で","で"],["、"],["小さな","ちいさな"]],[["探偵","たんてい"],["に","に"]],[["なる","なる","なる",5],["こと","こと"],["に","に"]],[["しました","しました","する",2],["。"]]],"tr":{"az":"Bir gün Yui məktəbdə yemək qutusunun qapağını açdı. Amma yumurta ruleti yox idi. Yui çox təəccübləndi. «Görəsən, kimsə onu yeyib?» deyə düşündü. Beləcə, balaca xəfiyyə olmağa qərar verdi.","en":"One day at school, Yui opened her lunch box. But the omelet was missing. Yui was very surprised. “I wonder if someone ate it,” she thought. So she decided to become a little detective.","ru":"Однажды в школе Юи открыла коробочку с обедом. Но яичного рулета там не было. Юи очень удивилась. «Неужели кто-то его съел?» – подумала она. И решила стать маленьким сыщиком."}},{"t":[[["まず","まず"],["、"],["隣","となり"],["の","の"]],[["席","せき"],["の","の"]],[["タケル","タケル"],["に","に"]],[["聞きました","ききました","聞く",2],["。"],["タケル","タケル"],["は","は"],["「"],["ぼく","ぼく"],["じゃ","じゃ"]],[["ない","ない"],["よ","よ"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["でも","でも"],["、"],["タケル","タケル"],["の","の"]],[["口","くち"],["に","に"],["は","は"]],[["黄色い","きいろい"]],[["もの","もの"],["が","が"]],[["ついて","ついて","つく",3]],[["いました","いました","いる",2],["。"],["ユイ","ユイ"],["に","に"]],[["じっと","じっと"]],[["見られて","みられて","見る",99],["、"],["タケル","タケル"],["は","は"]],[["あわてました","あわてました","あわてました",2],["。"],["それ","それ"],["は","は"]],[["卵","たまご"],["で","で"],["は","は"],["なく","なく","ない"],["、"],["カレー","カレー"],["でした","でした","です",9],["。"]]],"tr":{"az":"Əvvəlcə yanında oturan Takerudan soruşdu. Takeru «Mən etməmişəm» dedi. Amma onun ağzının kənarında sarı bir şey vardı. Yui ona diqqətlə baxanda Takeru özünü itirdi. Lakin bu, yumurta deyil, karri sousu idi.","en":"First, she asked Takeru, who sat beside her. Takeru said, “It wasn't me.” But there was something yellow around his mouth. When Yui stared at him, Takeru became nervous. It was not egg, though. It was curry.","ru":"Сначала она спросила Такэру, который сидел рядом. Такэру сказал: «Это не я». Но около его рта было что-то жёлтое. Когда Юи пристально посмотрела на него, Такэру занервничал. Однако это было не яйцо, а карри."}},{"t":[[["次","つぎ"],["に","に"],["、"],["ユイ","ユイ"],["は","は"]],[["友だち","ともだち"],["の","の"]],[["ハナ","ハナ"],["に","に"]],[["聞きました","ききました","聞く",2],["。"],["ハナ","ハナ"],["は","は"],["「"],["さっき","さっき"]],[["猫","ねこ"],["が","が"]],[["窓","まど"],["から","から"]],[["入って","はいって","入る",3]],[["きた","きた","くる",0],["よ","よ"],["」"],["と","と"]],[["教えました","おしえました","教える",2],["。"],["ユイ","ユイ"],["は","は"]],[["猫","ねこ"],["に","に"]],[["お弁当","おべんとう"],["を","を"]],[["食べられた","たべられた","食べる",98],["と","と"]],[["思いました","おもいました","思う",2],["。"],["でも","でも"],["、"],["教室","きょうしつ"],["の","の"]],[["床","ゆか"],["に","に"],["は","は"]],[["何","なん"],["も","も"]],[["落ちて","おちて","落ちる",3]],[["いませんでした","いませんでした","いる",4],["。"]]],"tr":{"az":"Sonra Yui rəfiqəsi Hanadan soruşdu. Hana «Bir az əvvəl pəncərədən pişik girmişdi» dedi. Yui yeməyini pişiyin yediyini düşündü. Amma sinfin döşəməsində heç bir yemək izi yox idi.","en":"Next, Yui asked her friend Hana. Hana told her, “A cat came in through the window a little while ago.” Yui thought the cat had eaten her lunch. But there were no crumbs or bits of food on the classroom floor.","ru":"Затем Юи спросила подругу Хану. Хана сказала: «Недавно через окно забралась кошка». Юи подумала, что кошка съела её обед. Но на полу класса не было никаких следов еды."}},{"t":[[["ユイ","ユイ"],["は","は"]],[["先生","せんせい"],["に","に"],["「"],["お弁当","おべんとう"],["を","を"]],[["調べても","しらべても","調べる",34]],[["いい","いい"],["です","です"],["か","か"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["先生","せんせい"],["に","に"],["は","は"],["「"],["授業中","じゅぎょうなか"],["に","に"]],[["お弁当","おべんとう"],["を","を"]],[["開けて","あけて","開ける",3],["は","は"]],[["いけません","いけません","いける",6],["」"],["と","と"]],[["注意","ちゅうい"],["されました","されました","する",27],["。"],["ユイ","ユイ"],["は","は"]],[["友だち","ともだち"],["に","に"]],[["笑われて","わらわれて","笑う",65],["、"],["少し","すこし"]],[["恥ずかしく","はずかしく"]],[["なりました","なりました","なる",2],["。"],["でも","でも"],["、"],["まだ","まだ"]],[["あきらめませんでした","あきらめませんでした","あきらめませんでした",4],["。"]]],"tr":{"az":"Yui müəllimdən «Yemək qutumu yoxlaya bilərəm?» deyə soruşdu. Müəllim ona «Dərs zamanı yemək qutusunu açmaq olmaz» deyərək xəbərdarlıq etdi. Dostları ona güldülər və Yui bir az utandı. Amma hələ təslim olmamışdı.","en":"Yui asked the teacher, “May I check my lunch box?” The teacher warned her, “You mustn't open your lunch box during class.” Her classmates laughed at her, and Yui felt a little embarrassed. But she still did not give up.","ru":"Юи спросила учителя: «Можно мне проверить коробочку с обедом?» Учитель сделал ей замечание: «Нельзя открывать обед во время урока». Одноклассники засмеялись, и Юи немного смутилась. Но она не собиралась сдаваться."}},{"t":[[["放課後","ほうかあと"],["、"],["ユイ","ユイ"],["は","は"]],[["家","いえ"],["に","に"]],[["帰って","かえって","帰る",3],["、"],["お母さん","おかあさん"],["に","に"]],[["話しました","はなしました","話す",2],["。"],["お母さん","おかあさん"],["は","は"]],[["急","きゅう"],["に","に"]],[["笑い","わらい","笑う",10],["出しました","だしました","出す",2],["。"],["「"],["今日","きょう"],["は","は"]],[["卵焼き","たまごやき"],["を","を"]],[["入れなかった","いれなかった","入れる",22],["の","の"],["よ","よ"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["ユイ","ユイ"],["は","は"],["「"],["えっ","えっ"],["、"],["どう","どう"],["して","して","する",3],["」"],["と","と"]],[["大きな","おおきな"]],[["声","こえ"],["で","で"]],[["聞きました","ききました","聞く",2],["。"]]],"tr":{"az":"Dərsdən sonra Yui evə qayıdıb hər şeyi anasına danışdı. Anası birdən gülməyə başladı. «Bu gün qutuya yumurta ruleti qoymamışdım» dedi. Yui təəccüblə «Nə? Niyə?» deyə ucadan soruşdu.","en":"After school, Yui returned home and told her mother everything. Her mother suddenly burst out laughing. “I didn't put any omelet in your lunch box today,” she said. “What? Why?” Yui asked loudly.","ru":"После школы Юи вернулась домой и всё рассказала маме. Мама вдруг рассмеялась. «Сегодня я не положила тебе яичный рулет», – сказала она. «Что? Почему?» – громко спросила Юи."}},{"t":[[["お母さん","おかあさん"],["は","は"]],[["冷蔵庫","れいぞうこ"],["から","から"]],[["小さな","ちいさな"]],[["箱","はこ"],["を","を"]],[["出しました","だしました","出す",2],["。"],["箱","はこ"],["に","に"],["は","は"]],[["かわいい","かわいい"]],[["卵焼き","たまごやき"],["が","が"]],[["たくさん","たくさん"]],[["入って","はいって","入る",3]],[["いました","いました","いる",2],["。"],["それ","それ"],["は","は"]],[["お父さん","おとうさん"],["に","に"]],[["よって","よって","よって",3]],[["作られた","つくられた","作る",55]],[["もの","もの"],["でした","でした","です",9],["。"],["今日","きょう"],["は","は"]],[["お母さん","おかあさん"],["の","の"]],[["誕生","たんじょう"],["日","ひ"],["で","で"],["、"],["お父さん","おとうさん"],["が","が"]],[["特別な","とくべつな","特別な",1]],[["夕ご飯","ゆうごはん"],["を","を"]],[["準備","じゅんび"],["して","して","する",3]],[["いた","いた","いる",0],["の","の"],["です","です"],["。"]]],"tr":{"az":"Anası soyuducudan balaca bir qutu çıxardı. Qutuda çoxlu gözəl yumurta ruleti vardı. Onları atası hazırlamışdı. Bu gün anasının ad günü idi və atası xüsusi axşam yeməyi hazırlayırdı.","en":"Her mother took a small box out of the refrigerator. Inside were many beautifully shaped rolled omelets. They had been made by Yui's father. It was her mother's birthday, and her father had been preparing a special dinner.","ru":"Мама достала из холодильника маленькую коробку. Внутри было много красивых яичных рулетов. Их приготовил папа Юи. Сегодня был мамин день рождения, и папа готовил особенный ужин."}},{"t":[[["その","その"],["夜","よる"],["、"],["ユイ","ユイ"],["は","は"]],[["お父さん","おとうさん"],["の","の"]],[["卵焼き","たまごやき"],["を","を"]],[["食べました","たべました","食べる",2],["。"],["お父さん","おとうさん"],["は","は"]],[["家族","かぞく"],["みんな","みんな"],["に","に"],["「"],["おいしい","おいしい"],["」"],["と","と"]],[["ほめられました","ほめられました","ほめられました",64],["。"],["ユイ","ユイ"],["は","は"]],[["先生","せんせい"],["に","に"]],[["注意","ちゅうい"],["された","された","する",55]],[["こと","こと"],["も","も"]],[["忘れて","わすれて","忘れる",3],["、"],["たくさん","たくさん"]],[["食べました","たべました","食べる",2],["。"],["そして","そして"],["「"],["今日","きょう"],["の","の"]],[["犯人","はんじん"],["は","は"]],[["お父さん","おとうさん"],["だった","だった","です",9],["ん","ん"],["だ","だ","です"],["ね","ね"],["」"],["と","と"]],[["言って","いって","言う",3],["、"],["みんな","みんな"],["を","を"]],[["笑わせました","わらわせました","笑う",16],["。"]]],"tr":{"az":"Həmin axşam Yui atasının hazırladığı yumurta ruletini yedi. Bütün ailə atasını «Çox dadlıdır!» deyərək təriflədi. Yui müəllimin xəbərdarlığını da unudub doyunca yedi. Sonra «Deməli, bugünkü sirrin günahkarı atam imiş!» dedi və hamını güldürdü.","en":"That evening, Yui ate the omelets her father had made. Everyone in the family praised him, saying, “Delicious!” Yui forgot all about being warned by her teacher and ate plenty. Then she said, “So Dad was the culprit all along!” and made everyone laugh.","ru":"В тот вечер Юи ела яичные рулеты, приготовленные папой. Вся семья хвалила его: «Очень вкусно!» Юи забыла даже о замечании учителя и с удовольствием поела. Потом она сказала: «Значит, виновником сегодняшней загадки был папа!» – и рассмешила всех."}}]}],"G":{"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"いい":{"b":"いい・良い (よい)","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"İ-sifətdir, lakin dəyişən formaları よい əsasından yaranır: よくない, よかった.","en":"An i-adjective whose inflected forms use よい: よくない, よかった.","ru":"И-прилагательное, изменяемые формы которого образуются от よい: よくない, よかった."}},"いう":{"b":"という","p":"ex","m":{"az":"adlı, deyilən","en":"called, named","ru":"под названием"},"n":{"az":"N という名前 = N adlı ad: 「かぐや」という名前 = «Kaquya» adı.","en":"N という名前 = the name \"N\".","ru":"N という名前 = имя «N»."}},"いける":{"b":"行ける (いける)","p":"v","m":{"az":"gedə bilmək","en":"to be able to go","ru":"мочь пойти"},"n":{"az":"いけません qadağa ifadəsində olmaz deməkdir və bu halda 行ける potensial felindən fərqlidir.","en":"いけません can mean must not in prohibitions and is then distinct from the potential verb 行ける.","ru":"いけません в запретах означает нельзя и отличается от потенциального глагола 行ける."}},"いっしょ":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlikdə","en":"together","ru":"вместе"},"n":{"az":"いっしょに = birlikdə.","en":"いっしょに = together.","ru":"いっしょに = вместе."}},"いつ":{"b":"いつ","p":"pr","m":{"az":"nə vaxt","en":"when","ru":"когда"},"n":{"az":"Adətən に qəbul etmir: いつ行きますか.","en":"Usually takes no に: いつ行きますか.","ru":"Обычно употребляется без に: いつ行きますか."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"うれしい":{"b":"嬉しい (うれしい)","p":"ai","m":{"az":"sevincli, şad","en":"happy, glad","ru":"радостный, довольный"},"n":{"az":"い sifətidir, うれし bağlayıcı və ya başqa forma yaratmaq üçün əsasdır.","en":"An i-adjective, with うれし as the stem used to form other expressions.","ru":"Прилагательное на い, うれし - основа для образования других форм."}},"えっ":{"b":"えっ","p":"in","m":{"az":"nə, doğrudan?","en":"huh, what, really","ru":"что, правда, а?"},"n":{"az":"Təəccüb və ya eşidiləni anlamama bildirir; qeyri-rəsmi reaksiyadır.","en":"An informal reaction expressing surprise or failure to hear or understand.","ru":"Неформальное междометие, выражающее удивление или непонимание услышанного."}},"おいしい":{"b":"おいしい","p":"ai","m":{"az":"dadlı","en":"delicious, tasty","ru":"вкусный"},"n":{"az":"い-sifətdir: おいしくない = dadlı deyil.","en":"An i-adjective: おいしくない = not tasty.","ru":"Прилагательное на い: おいしくない = невкусный."}},"お母さん":{"b":"お母さん (おかあさん)","p":"n","m":{"az":"ana","en":"mother; mom","ru":"мама; мать"},"n":{"az":"Anaya müraciətdə və başqasının anası haqqında işlənir; kənar şəxslərə öz anandan danışarkən adətən 母 deyilir.","en":"Used to address your mother or refer to someone else's; use 母 for your own mother when speaking to outsiders.","ru":"Используется при обращении к маме или о чужой матери; о своей матери посторонним обычно говорят 母."}},"お父さん":{"b":"お父さん (おとうさん)","p":"n","m":{"az":"ata","en":"father; dad","ru":"папа; отец"},"n":{"az":"Ataya müraciətdə və başqasının atası haqqında işlənir; kənar şəxslərə öz atandan danışarkən adətən 父 deyilir.","en":"Used to address your father or refer to someone else's; use 父 for your own father when speaking to outsiders.","ru":"Используется при обращении к папе или о чужом отце; о своём отце посторонним обычно говорят 父."}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"かける":{"b":"掛ける (かける)","p":"v","m":{"az":"asmaq; qoymaq","en":"hang; put on","ru":"вешать; ставить"},"n":{"az":"Təsirli feldir: 電話をかける zəng etmək, 火にかける oda qoymaq, 声をかける səslənmək deməkdir.","en":"A transitive verb: 電話をかける means make a call, 火にかける put over heat, and 声をかける call out to someone.","ru":"Переходный глагол: 電話をかける значит позвонить, 火にかける поставить на огонь, 声をかける обратиться к кому-либо."}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"きれい":{"b":"きれい","p":"an","m":{"az":"gözəl, təmiz","en":"beautiful, clean","ru":"красивый, чистый"},"n":{"az":"な-sifətdir: きれいな花 = gözəl çiçək; い ilə bitsə də い-sifət deyil.","en":"A na-adjective despite ending in い: きれいな花 = beautiful flower.","ru":"Это な-прилагательное, несмотря на окончание い: きれいな花 = красивый цветок."}},"くる":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"come","ru":"приходить"},"n":{"az":"Qaydasız feldir: きます, きました və きて formalarını alır.","en":"An irregular verb with the forms きます, きました, and きて.","ru":"Неправильный глагол с формами きます, きました и きて."}},"こと":{"b":"こと","p":"n","m":{"az":"iş; hadisə; məsələ","en":"thing; matter; event","ru":"дело; событие; обстоятельство"},"n":{"az":"Felə qoşularaq hərəkəti isimləşdirir: 読むこと oxumaq hərəkəti.","en":"It nominalizes verbs: 読むこと means the act of reading.","ru":"Превращает глагол в существительное: 読むこと означает чтение."}},"さっき":{"b":"さっき","p":"n","m":{"az":"bayaq, bir az əvvəl","en":"a moment ago","ru":"только что"}},"しっぽ":{"b":"尻尾 (しっぽ)","p":"n","m":{"az":"quyruq","en":"tail","ru":"хвост"}},"じゃ":{"b":"じゃ (← では)","p":"cp","m":{"az":"inkarın birinci hissəsi","en":"first part of the negative","ru":"первая часть отрицания"},"n":{"az":"じゃ ありません birlikdə 'deyil' deməkdir: 学生じゃ ありません = tələbə deyiləm. Rəsmi yazıda では ありません.","en":"じゃ ありません together means 'is not': 学生じゃ ありません = I am not a student. Formal writing: では ありません.","ru":"じゃ ありません вместе = 'не является': 学生じゃ ありません = я не студент. В официальной речи では ありません."}},"すぐ":{"b":"すぐ","p":"ad","m":{"az":"tez, dərhal","en":"soon, immediately","ru":"сразу, скоро"},"n":{"az":"すぐに = dərhal.","en":"すぐに = right away.","ru":"すぐに = сразу."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"そう":{"b":"そう","p":"ad","m":{"az":"elə; belə","en":"so; that way","ru":"так"},"n":{"az":"そうです təsdiq, そうします isə deyilən şəkildə hərəkət etməyi bildirir.","en":"そうです confirms something; そうします means to do it that way.","ru":"そうです выражает подтверждение, а そうします означает сделать именно так."}},"そこ":{"b":"そこ","p":"pr","m":{"az":"ora","en":"there","ru":"там"},"n":{"az":"Dinləyiciyə yaxın və ya söhbətdə artıq qeyd olunan yeri göstərir.","en":"Refers to a place near the listener or already mentioned.","ru":"Обозначает место рядом с собеседником или уже упомянутое место."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"そば":{"b":"そば","p":"n","m":{"az":"yan, yaxınlıq","en":"side, nearby","ru":"рядом, около"},"n":{"az":"N の そば = N-in yanında.","en":"N の そば = beside N.","ru":"N の そば = рядом с N."}},"それ":{"b":"それ","p":"pr","m":{"az":"o; həmin şey","en":"that; that thing","ru":"то; эта вещь"},"n":{"az":"Dinləyənə yaxın və ya əvvəl qeyd edilmiş şeyi bildirir.","en":"Refers to something near the listener or already mentioned.","ru":"Указывает на предмет рядом со слушающим или на уже упомянутое."}},"それから":{"b":"それから","p":"cj","m":{"az":"sonra, ondan sonra","en":"then, after that","ru":"потом, затем"}},"そんな":{"b":"そんな","p":"dm","m":{"az":"elə, o cür","en":"that kind of, such","ru":"такой, подобный"},"n":{"az":"そんな + isim; そんなに + sifət və ya fel: そんなに難しくない = o qədər də çətin deyil.","en":"そんな modifies nouns; そんなに modifies adjectives or verbs: そんなに難しくない = not that difficult.","ru":"そんな определяет существительные, а そんなに усиливает прилагательные и глаголы: そんなに難しくない = не так уж трудно."}},"たくさん":{"b":"たくさん","p":"ad","m":{"az":"çox; çoxlu","en":"many; much; a lot","ru":"много"},"n":{"az":"İsimlə たくさんの本, fellə isə たくさん食べる şəklində işlənir.","en":"Use たくさんの本 with a noun and たくさん食べる with a verb.","ru":"С существительным употребляется たくさんの本, с глаголом たくさん食べる."}},"だれ":{"b":"だれ","p":"pr","m":{"az":"kim","en":"who","ru":"кто"},"n":{"az":"Sual sözü: あの人はだれですか = O adam kimdir? Daha nəzakətli forması どなた.","en":"Question word: あの人はだれですか = Who is that person? More polite: どなた.","ru":"Вопросительное слово: あの人はだれですか = Кто этот человек? Вежливее: どなた."}},"つく":{"b":"つく (着く)","p":"v","m":{"az":"çatmaq, yetişmək","en":"to arrive, to reach","ru":"прибывать, добираться"},"n":{"az":"I qrup feldir: 駅に着く = stansiyaya çatmaq; つきませんでした = çatmadı.","en":"A Group 1 verb: 駅に着く = to arrive at the station; つきませんでした = did not arrive.","ru":"Глагол I группы: 駅に着く = прибыть на станцию; つきませんでした = не прибыл."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"できる":{"b":"できる","p":"v","m":{"az":"bacarmaq; hazır olmaq","en":"be able to; be ready","ru":"мочь; быть готовым"},"n":{"az":"Bacarığı 日本語ができる, tamamlanmanı isə ご飯ができる kimi ifadə edir.","en":"Expresses ability in 日本語ができる and completion in ご飯ができる.","ru":"Выражает умение в 日本語ができる и готовность в ご飯ができる."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とき":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, an","en":"time, moment","ru":"время, момент"}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"どう":{"b":"どう","p":"ad","m":{"az":"necə, nə cür","en":"how, in what way","ru":"как, каким образом"},"n":{"az":"どうですか = necədir, nə fikirləşirsiniz?","en":"どうですか asks how something is or what someone thinks.","ru":"どうですか означает «как это?» или «что вы думаете?»."}},"ない":{"b":"無い (ない)","p":"ai","m":{"az":"yoxdur; mövcud deyil","en":"not exist; not have","ru":"нет; отсутствует"},"n":{"az":"İ-sifət kimi dəyişir: なく və なかった; felə qoşulduqda inkar da bildirir.","en":"Inflects like an i-adjective: なく and なかった; attached to a verb, it also marks negation.","ru":"Изменяется как и-прилагательное: なく и なかった; при глаголе также выражает отрицание."}},"なでる":{"b":"撫でる (なでる)","p":"v","m":{"az":"sığallamaq","en":"to stroke; to pet","ru":"гладить; ласкать"}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"ね":{"b":"ね","p":"pt","m":{"az":"elə deyilmi?; hə?","en":"right?; isn't it?","ru":"правда?; ведь"},"n":{"az":"Cümlə sonunda təsdiq və ortaq hiss bildirir, məsələn 寒いですね, əmri yumşaldır, məsələn 来てね, danışıqda isə 私はね kimi diqqət çəkir.","en":"At sentence end it seeks agreement or shares a feeling, as in 寒いですね, softens requests, as in 来てね, and conversationally draws attention, as in 私はね.","ru":"В конце фразы выражает ожидание согласия или общее чувство, как в 寒いですね, смягчает просьбу, как в 来てね, и привлекает внимание, как в 私はね."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"ひみつ":{"b":"秘密 (ひみつ)","p":"n","m":{"az":"sirr; gizli məlumat","en":"secret","ru":"секрет; тайна"},"n":{"az":"秘密の söz birləşməsi gizli mənasını verir.","en":"秘密の means secret or confidential before a noun.","ru":"秘密の перед существительным означает тайный или секретный."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"ぼく":{"b":"僕 (ぼく)","p":"pr","m":{"az":"mən","en":"I","ru":"я"},"n":{"az":"Əsasən oğlanların və kişilərin işlətdiyi birinci şəxs əvəzliyidir.","en":"A first-person pronoun used mainly by boys and men.","ru":"Местоимение первого лица, употребляемое преимущественно мальчиками и мужчинами."}},"まず":{"b":"まず","p":"ad","m":{"az":"əvvəlcə; ilk növbədə","en":"first; to begin with","ru":"сначала; прежде всего"}},"また":{"b":"また","p":"ad","m":{"az":"yenə, təkrar","en":"again","ru":"снова"}},"まだ":{"b":"まだ","p":"ad","m":{"az":"hələ","en":"still, yet","ru":"ещё"}},"まで":{"b":"まで","p":"pt","m":{"az":"qədər, hətta","en":"until, as far as, even","ru":"до, даже"},"n":{"az":"Zaman və məkan həddini bildirir: 五時まで “saat beşə qədər”, 駅まで “stansiyaya qədər”; təəccüblü əlavəni də vurğulayır: 子どもまで “hətta uşaqlar”.","en":"Marks a time or place limit, as in 五時まで “until five” and 駅まで “as far as the station,” and surprising inclusion, as in 子どもまで “even children.”","ru":"Обозначает предел времени или места: 五時まで «до пяти», 駅まで «до станции», а также неожиданное включение: 子どもまで «даже дети»."}},"まま":{"b":"まま","p":"n","m":{"az":"olduğu kimi, ...-mış halda","en":"as it is","ru":"как есть"},"n":{"az":"入ったまま = içində qalaraq.","en":"入ったまま = while staying inside.","ru":"入ったまま = оставаясь внутри."}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかし":{"b":"昔 (むかし)","p":"n","m":{"az":"çox qədim zaman","en":"long ago","ru":"давным-давно"},"n":{"az":"むかし むかし = 'biri var idi, biri yox idi' – nağılların başlanğıcı.","en":"むかし むかし = 'once upon a time' – the opening of tales.","ru":"むかし むかし = 'давным-давно' – начало сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もらう":{"b":"もらう","p":"v","m":{"az":"almaq, hədiyyə almaq","en":"to receive, to get","ru":"получать"},"n":{"az":"Verən şəxs に və ya から ilə göstərilir: 友達に本をもらう.","en":"The giver takes に or から: 友達に本をもらう, receive a book from a friend.","ru":"Даритель обозначается через に или から: 友達に本をもらう, получить книгу от друга."}},"やがて":{"b":"やがて","p":"ad","m":{"az":"bir müddət sonra; nəhayət","en":"before long; eventually","ru":"вскоре; со временем"}},"やさしい":{"b":"優しい (やさしい)","p":"ai","m":{"az":"mülayim, mehriban","en":"gentle, kind","ru":"мягкий, добрый"},"n":{"az":"やさしかった = mülayim idi (i-sifətin keçmiş zamanı: い → かった).","en":"やさしかった = was gentle (past of i-adjective: い → かった).","ru":"やさしかった = был мягким (прошедшее i-прил.: い → かった)."}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よう":{"b":"よう","p":"an","m":{"az":"kimi, sanki","en":"like, as if","ru":"подобно, словно"},"n":{"az":"Bənzətmə bildirir: Nのような isimdən əvvəl, Nのように feldən əvvəl, Nのようです isə cümlənin sonunda işlənir.","en":"Expresses resemblance: Nのような modifies a noun, Nのように modifies a verb, and Nのようです ends a sentence.","ru":"Выражает сходство: Nのような стоит перед существительным, Nのように перед глаголом, а Nのようです завершает предложение."}},"よく":{"b":"よく","p":"ad","m":{"az":"yaxşıca, diqqətlə","en":"well, carefully","ru":"хорошо, внимательно"}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"ん":{"b":"ん (← の)","p":"pt","m":{"az":"(izah bildirir)","en":"(explanatory)","ru":"(пояснение)"},"n":{"az":"〜んです / 〜のです: səbəb və ya izah verəndə işlənir; danışıqda の → ん.","en":"〜んです / 〜のです adds an explanation; in speech の becomes ん.","ru":"〜んです / 〜のです – объяснение; в речи の → ん."}},"カレー":{"b":"カレー","p":"n","m":{"az":"karri, karri yeməyi","en":"curry, curry dish","ru":"карри, блюдо карри"}},"ノート":{"b":"ノート","p":"n","m":{"az":"dəftər","en":"notebook","ru":"тетрадь"}},"ハナ":{"b":"ハナ","p":"nm","m":{"az":"Hana (qız adı)","en":"Hana (girl's name)","ru":"Хана (женское имя)"}},"ミナ":{"b":"ミナ","p":"nm","m":{"az":"Mina","en":"Mina","ru":"Мина"}},"ユイ":{"b":"ユイ","p":"nm","m":{"az":"Yui","en":"Yui","ru":"Юи"}},"ロボット":{"b":"ロボット","p":"n","m":{"az":"robot","en":"robot","ru":"робот"},"n":{"az":"Katakana ilə yazılır, çünki xarici mənşəli sözdür.","en":"Written in katakana because it is a loanword.","ru":"Пишется катаканой, так как это заимствование."}},"一つ":{"b":"一つ (ひとつ)","p":"n","m":{"az":"bir (dənə)","en":"one (thing)","ru":"одна (штука)"},"n":{"az":"Ümumi sayğac: 一つ, 二つ, 三つ.","en":"General counter: 一つ, 二つ, 三つ.","ru":"Общий счёт: 一つ, 二つ, 三つ."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"人":{"b":"人 (ひと)","p":"n","m":{"az":"adam, insan","en":"person","ru":"человек"},"n":{"az":"Tək işlənəndə ひと oxunur. Ölkə adından sonra じん olur: 日本人 (にほんじん) = yapon.","en":"Read ひと on its own. After a country it becomes じん: 日本人 = Japanese person.","ru":"Отдельно читается ひと. После названия страны – じん: 日本人 = японец."}},"人たち":{"b":"人たち (ひとたち)","p":"n","m":{"az":"adamlar, camaat","en":"people","ru":"люди"}},"今":{"b":"今 (いま)","p":"n","m":{"az":"indi","en":"now","ru":"сейчас"},"n":{"az":"今も = indi də.","en":"今も = even now.","ru":"今も = и сейчас."}},"今度":{"b":"今度 (こんど)","p":"n","m":{"az":"bu dəfə, gələn dəfə","en":"this time, next time","ru":"на этот раз, в следующий раз"},"n":{"az":"Kontekstdən asılı olaraq indiki və ya növbəti hadisəni bildirir.","en":"Depending on context, it refers to the present occasion or the next one.","ru":"В зависимости от контекста обозначает нынешний или следующий случай."}},"今日":{"b":"今日 (きょう)","p":"n","m":{"az":"bu gün","en":"today","ru":"сегодня"}},"何":{"b":"何 (なに・なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何ですか və 何時 kimi birləşmələrdə なん, 何を kimi hallarda isə なに oxunur.","en":"Read なん in expressions such as 何ですか and 何時, but なに in 何を.","ru":"Читается なん в сочетаниях 何ですか и 何時, но なに в 何を."}},"作る":{"b":"作る (つくる)","p":"v","m":{"az":"düzəltmək, yaratmaq","en":"to make","ru":"делать, создавать"},"n":{"az":"作ったのでした = (məlum oldu ki) düzəltmişdilər – izah bildirir.","en":"作ったのでした = (it turned out) they had made him.","ru":"作ったのでした = (оказалось) создали его."}},"元気":{"b":"元気 (げんき)","p":"an","m":{"az":"gümrah; sağlam","en":"energetic; well","ru":"бодрый; здоровый"},"n":{"az":"な-sifətidir: 元気な子; 元気です = özünü yaxşı hiss edir.","en":"A な-adjective: 元気な子; 元気です means being well.","ru":"な-прилагательное: 元気な子; 元気です означает хорошее самочувствие."}},"先生":{"b":"先生 (せんせい)","p":"n","m":{"az":"müəllim; həkim","en":"teacher; doctor","ru":"учитель; доктор"},"n":{"az":"Başqasına müraciət kimi işlənir (ミミ先生 = Mimi həkim). Özün haqqında 先生 demirsən, 教師 deyirsən.","en":"Used to address others (ミミ先生 = Doctor Mimi). Never about yourself – then you say 教師.","ru":"Используется как обращение (ミミ先生 = доктор Мими). О себе так не говорят – говорят 教師."}},"光":{"b":"光 (ひかり)","p":"n","m":{"az":"işıq","en":"light","ru":"свет"}},"光る":{"b":"光る (ひかる)","p":"v","m":{"az":"parlamaq, işıq saçmaq","en":"to shine","ru":"светиться, сиять"},"n":{"az":"光るランプ = parlayan lampa: feil isimdən əvvəl təyin kimi gəlir.","en":"光るランプ = a glowing lamp: a verb before a noun describes it.","ru":"光るランプ = светящаяся лампа: глагол перед сущ. – определение."}},"入る":{"b":"入る (はいる)","p":"v","m":{"az":"girmək","en":"to enter","ru":"входить"},"n":{"az":"入り、 = girib (feilin kökü ilə bağlama).","en":"入り、 = went in and ...","ru":"入り、 = вошла и ..."}},"入れる":{"b":"入れる (いれる)","p":"v","m":{"az":"içəri qoymaq; daxil etmək","en":"to put in; to insert","ru":"класть внутрь; вставлять"},"n":{"az":"Təsirlidir: 箱に入れる; təsirsiz qarşılığı 入る-dur.","en":"Transitive: 箱に入れる; its intransitive partner is 入る.","ru":"Переходный: 箱に入れる; непереходная пара: 入る."}},"冷蔵庫":{"b":"冷蔵庫 (れいぞうこ)","p":"n","m":{"az":"soyuducu","en":"refrigerator","ru":"холодильник"}},"出す":{"b":"出す (だす)","p":"v","m":{"az":"çıxarmaq","en":"to take out","ru":"вынимать"}},"出る":{"b":"出る (でる)","p":"v","m":{"az":"çıxmaq","en":"to go out","ru":"выходить"},"n":{"az":"庭に出る = bağçaya çıxmaq.","en":"庭に出る = go out into the garden.","ru":"庭に出る = выйти в сад."}},"初め":{"b":"初め (はじめ)","p":"n","m":{"az":"başlanğıc, ilk vaxt","en":"beginning, start","ru":"начало"},"n":{"az":"初めに əvvəlcə deməkdir, 始める isə başlamaq felidir.","en":"初めに means first or at the beginning, while 始める is the verb to begin.","ru":"初めに означает сначала, а 始める - глагол начинать."}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"助ける":{"b":"助ける (たすける)","p":"v","m":{"az":"kömək etmək; xilas etmək","en":"help; rescue","ru":"помогать; спасать"},"n":{"az":"Təsirli feldir və kömək edilən şəxs を ilə göstərilir; 助かる xilas olmaq deməkdir.","en":"A transitive verb with the person helped marked by を; 助かる means to be saved.","ru":"Переходный глагол: человек, которому помогают, оформляется を; 助かる означает спастись."}},"動く":{"b":"動く (うごく)","p":"v","m":{"az":"hərəkət etmək, işləmək","en":"to move, to operate","ru":"двигаться, работать"},"n":{"az":"I qrup feldir: 動きました = hərəkət etdi; 動かす = hərəkət etdirmək.","en":"A Group 1 verb: 動きました = moved; 動かす = to move something.","ru":"Глагол I группы: 動きました = двигался; 動かす = приводить в движение."}},"卵":{"b":"卵 (たまご)","p":"n","m":{"az":"yumurta","en":"egg","ru":"яйцо"}},"取る":{"b":"取る (とる)","p":"v","m":{"az":"götürmək, almaq","en":"to take, to pick up","ru":"брать, поднимать"},"n":{"az":"Əşyanı götürmək üçün 取る, şəkil çəkmək üçün eyni oxunuşlu 撮る işlənir.","en":"Use 取る for taking an object and the identically pronounced 撮る for taking a photo.","ru":"Для взятия предмета используется 取る, а для фотографии используется 撮る с тем же чтением."}},"口":{"b":"口 (くち)","p":"n","m":{"az":"ağız, açılış","en":"mouth, opening","ru":"рот, отверстие"}},"名前":{"b":"名前 (なまえ)","p":"n","m":{"az":"ad","en":"name","ru":"имя"}},"呼ぶ":{"b":"呼ぶ (よぶ)","p":"v","m":{"az":"çağırmaq, adlandırmaq","en":"call, name","ru":"звать, называть"},"n":{"az":"Şəxs を ilə göstərilir; AをBと呼ぶ “A-nı B adlandırmaq” deməkdir.","en":"The person takes を; AをBと呼ぶ means “call A B.”","ru":"Человек обозначается с を; AをBと呼ぶ означает «называть A именем B»."}},"困る":{"b":"困る (こまる)","p":"v","m":{"az":"çətin vəziyyətdə qalmaq; çətinlik çəkmək","en":"be in trouble; be at a loss","ru":"оказаться в затруднении"},"n":{"az":"困っている hazırda çətin vəziyyətdə olmağı bildirir; səbəb に ilə göstərilə bilər.","en":"困っている describes being in difficulty; the cause can be marked by に.","ru":"困っている описывает состояние затруднения; причина может оформляться に."}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"夕方":{"b":"夕方 (ゆうがた)","p":"n","m":{"az":"axşamüstü","en":"evening","ru":"вечер"}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"大切":{"b":"大切 (たいせつ)","p":"an","m":{"az":"vacib, əziz","en":"important, precious","ru":"важный, дорогой"},"n":{"az":"Na-sifətidir: 大切な物 “əziz əşya”; 大切にする “qayğı ilə yanaşmaq, əziz tutmaq” deməkdir.","en":"A na-adjective: 大切な物 “a precious thing”; 大切にする means “cherish or take good care of.”","ru":"Прилагательное на な: 大切な物 «дорогая вещь»; 大切にする означает «беречь, дорожить»."}},"大好き":{"b":"大好き (だいすき)","p":"an","m":{"az":"çox sevimli, çox xoşlamaq","en":"to love, to like very much","ru":"очень любить, обожать"},"n":{"az":"な-sifətdir: 音楽が大好きです = musiqini çox sevirəm.","en":"A na-adjective: 音楽が大好きです = I love music.","ru":"な-прилагательное: 音楽が大好きです = я очень люблю музыку."}},"大学":{"b":"大学 (だいがく)","p":"n","m":{"az":"universitet","en":"university","ru":"университет"}},"女の子":{"b":"女の子 (おんなのこ)","p":"n","m":{"az":"qız uşağı","en":"girl","ru":"девочка"}},"子":{"b":"子 (こ)","p":"n","m":{"az":"uşaq; övlad","en":"child","ru":"ребёнок"},"n":{"az":"わたしの子 = mənim övladım.","en":"わたしの子 = my child.","ru":"わたしの子 = мой ребёнок."}},"子ども":{"b":"子ども (こども)","p":"n","m":{"az":"uşaq","en":"child","ru":"ребёнок"}},"子どもたち":{"b":"子どもたち (こどもたち)","p":"n","m":{"az":"uşaqlar","en":"children","ru":"дети"},"n":{"az":"たち insanları və bəzən canlıları bildirən sözlərə cəm və ya qrup mənası verir.","en":"たち marks a plural or group, mainly with words for people and sometimes other living beings.","ru":"たち обозначает множественность или группу, главным образом у слов, называющих людей, иногда других живых существ."}},"学校":{"b":"学校 (がっこう)","p":"n","m":{"az":"məktəb","en":"school","ru":"школа"}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"家族":{"b":"家族 (かぞく)","p":"n","m":{"az":"ailə","en":"family","ru":"семья"}},"小さい":{"b":"小さい (ちいさい)","p":"ai","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"i-sifət; isimdən əvvəl olduğu kimi gəlir: 小さい子 = balaca uşaq.","en":"i-adjective; goes straight before a noun: 小さい子 = a little child.","ru":"i-прилагательное; ставится прямо перед существительным."}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"席":{"b":"席 (せき)","p":"n","m":{"az":"yer; oturacaq yeri","en":"seat; place","ru":"место"},"n":{"az":"Nəqliyyatda, sinifdə və ya masada bir şəxsin yerini bildirə bilər.","en":"Can mean someone's place on transport, in class, or at a table.","ru":"Может обозначать чьё-либо место в транспорте, классе или за столом."}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"年":{"b":"年 (とし)","p":"n","m":{"az":"yaş; il","en":"age; year","ru":"возраст; год"},"n":{"az":"Burada 'yaş' mənasında とし oxunur. İl sayğacı kimi ねん: 二年.","en":"Here 'age', read とし. As a year counter: ねん.","ru":"Здесь 'возраст', читается とし. Как счёт лет – ねん."}},"床":{"b":"床 (ゆか)","p":"n","m":{"az":"döşəmə","en":"floor","ru":"пол"}},"店":{"b":"店 (みせ)","p":"n","m":{"az":"mağaza; dükan","en":"shop; store","ru":"магазин; лавка"}},"座る":{"b":"座る (すわる)","p":"v","m":{"az":"oturmaq","en":"sit down","ru":"садиться"},"n":{"az":"Oturulan yer に ilə göstərilir: 椅子に座る “stulda oturmaq”.","en":"The seat or sitting place takes に: 椅子に座る “sit on a chair.”","ru":"Место обозначается с に: 椅子に座る «сесть на стул»."}},"強い":{"b":"強い (つよい)","p":"ai","m":{"az":"güclü, qüvvətli","en":"strong, powerful","ru":"сильный"},"n":{"az":"い-sifətdir; əksi 弱い - zəif.","en":"An i-adjective; its opposite is 弱い, weak.","ru":"Это i-прилагательное; антоним 弱い - слабый."}},"役":{"b":"役 (やく)","p":"n","m":{"az":"rol, vəzifə","en":"role, duty","ru":"роль, обязанность"},"n":{"az":"役に立つ sabit ifadəsi “faydalı olmaq” deməkdir.","en":"The set phrase 役に立つ means “be useful.”","ru":"Устойчивое выражение 役に立つ означает «быть полезным»."}},"待つ":{"b":"待つ (まつ)","p":"v","m":{"az":"gözləmək","en":"wait for","ru":"ждать"},"n":{"az":"Gözlənilən şəxs və ya şey を ilə işlənir; て-forması 待って olur.","en":"The person or thing awaited takes を; the て-form is 待って.","ru":"Тот, кого ждут, или то, чего ждут, обозначается с を; форма на て: 待って."}},"後":{"b":"後 (あと)","p":"n","m":{"az":"sonra; arxası","en":"after; behind","ru":"после; позади"},"n":{"az":"時間の後 = vaxtdan sonra; 後で = sonra; bəzi birləşmələrdə ご oxunur.","en":"時間の後 means after a time; 後で means later; some compounds use the reading ご.","ru":"時間の後 означает «после указанного времени», 後で = потом; в некоторых сочетаниях читается ご."}},"心":{"b":"心 (こころ)","p":"n","m":{"az":"ürək, qəlb, könül","en":"heart, mind, spirit","ru":"сердце, душа, разум"},"n":{"az":"Burada fiziki orqandan çox hiss və düşüncəni bildirir.","en":"Usually refers to feelings or the mind rather than the physical organ.","ru":"Обычно обозначает чувства или душу, а не физический орган."}},"心配":{"b":"心配 (しんぱい)","p":"n","m":{"az":"narahatlıq, qayğı","en":"worry, concern","ru":"беспокойство, тревога"},"n":{"az":"心配する “narahat olmaq” deməkdir; 心配な şəklində na-sifəti kimi də işlənir.","en":"心配する means “worry”; 心配な is also used as a na-adjective.","ru":"心配する означает «беспокоиться»; форма 心配な также употребляется как прилагательное на な."}},"忘れる":{"b":"忘れる (わすれる)","p":"v","m":{"az":"unutmaq","en":"to forget","ru":"забывать"},"n":{"az":"Nを忘れる həm nəyisə unutmaq, həm də bir yerdə qoyub gəlmək mənasında işlənir.","en":"Nを忘れる can mean to forget something or leave it behind.","ru":"Nを忘れる может означать забыть что-либо или оставить это где-либо."}},"怒る":{"b":"怒る (おこる)","p":"v","m":{"az":"hirslənmək; danlamaq","en":"to get angry; to scold","ru":"сердиться; ругать"},"n":{"az":"Hirslənmək üçün 人に怒る, danlamaq üçün 人を怒る işlənir.","en":"人に怒る means to be angry with someone; 人を怒る means to scold someone.","ru":"人に怒る означает сердиться на кого-то, а 人を怒る означает ругать кого-то."}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"急":{"b":"急 (きゅう)","p":"an","m":{"az":"qəfil, birdən","en":"sudden","ru":"внезапный"},"n":{"az":"急に = birdən, qəfildən.","en":"急に = suddenly.","ru":"急に = вдруг."}},"手":{"b":"手 (て)","p":"n","m":{"az":"əl","en":"hand","ru":"рука"}},"押す":{"b":"押す (おす)","p":"v","m":{"az":"basmaq; itələmək","en":"to push; to press","ru":"толкать; нажимать"},"n":{"az":"ボタンを押す düyməni basmaq deməkdir.","en":"ボタンを押す means to press a button.","ru":"ボタンを押す означает нажать кнопку."}},"振る":{"b":"振る (ふる)","p":"v","m":{"az":"yelləmək; silkələmək","en":"wave; shake","ru":"махать; трясти"},"n":{"az":"手を振る əl yelləmək, 首を振る isə başı yelləmək deməkdir.","en":"手を振る means to wave a hand; 首を振る means to shake one's head.","ru":"手を振る означает махать рукой, а 首を振る качать головой."}},"握る":{"b":"握る (にぎる)","p":"v","m":{"az":"(əlində) tutmaq, sıxmaq","en":"to grasp, hold","ru":"сжимать, держать"},"n":{"az":"手をにぎる = əlini tutmaq.","en":"手をにぎる = hold someone's hand.","ru":"手をにぎる = взять за руку."}},"放課後":{"b":"放課後 (ほうかご)","p":"n","m":{"az":"dərsdən sonra","en":"after school","ru":"после уроков"}},"教える":{"b":"教える (おしえる)","p":"v","m":{"az":"öyrətmək; demək (məlumat vermək)","en":"to teach; to tell","ru":"учить; сообщать"},"n":{"az":"名前を教えてください = adınızı deyin (zəhmət olmasa).","en":"名前を教えてください = please tell me your name.","ru":"名前を教えてください = скажите, пожалуйста, имя."}},"教室":{"b":"教室 (きょうしつ)","p":"n","m":{"az":"sinif otağı, auditoriya","en":"classroom","ru":"класс, аудитория"}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"星":{"b":"星 (ほし)","p":"n","m":{"az":"ulduz","en":"star","ru":"звезда"}},"春":{"b":"春 (はる)","p":"n","m":{"az":"yaz (fəsil)","en":"spring","ru":"весна"}},"時計":{"b":"時計 (とけい)","p":"n","m":{"az":"saat","en":"clock; watch","ru":"часы"}},"時間":{"b":"時間 (じかん)","p":"n","m":{"az":"vaxt, saat","en":"time, hour","ru":"время, час"},"n":{"az":"食べる時間 = yemək vaxtı (feil isimdən əvvəl).","en":"食べる時間 = the time to eat.","ru":"食べる時間 = время еды."}},"書く":{"b":"書く (かく)","p":"v","m":{"az":"yazmaq","en":"to write","ru":"писать"},"n":{"az":"「森」と書く = «Mori» yazmaq. 書いてある = yazılıb (yazılı durur).","en":"「森」と書く = write \"Mori\". 書いてある = is written.","ru":"「森」と書く = написать «Мори». 書いてある = написано."}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"止まる":{"b":"止まる (とまる)","p":"v","m":{"az":"dayanmaq","en":"to stop","ru":"останавливаться"},"n":{"az":"Təsirsizdir: バスが止まる; təsirli qarşılığı 止める-dir.","en":"Intransitive: バスが止まる; its transitive partner is 止める.","ru":"Непереходный: バスが止まる; переходная пара: 止める."}},"歩く":{"b":"歩く (あるく)","p":"v","m":{"az":"yerimək; piyada getmək","en":"walk","ru":"ходить; идти пешком"},"n":{"az":"歩いて piyada deməkdir; keçilən yol を ilə göstərilə bilər: 道を歩く.","en":"歩いて means on foot; the route can take を: 道を歩く.","ru":"歩いて означает пешком; путь может оформляться を: 道を歩く."}},"毎日":{"b":"毎日 (まいにち)","p":"n","m":{"az":"hər gün","en":"every day","ru":"каждый день"}},"毎朝":{"b":"毎朝 (まいあさ)","p":"n","m":{"az":"hər səhər","en":"every morning","ru":"каждое утро"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎朝働きます.","en":"Takes no に as a time expression: 毎朝働きます.","ru":"При обозначении времени употребляется без に: 毎朝働きます."}},"水":{"b":"水 (みず)","p":"n","m":{"az":"su","en":"water","ru":"вода"},"n":{"az":"水 adətən soyuq və ya otaq temperaturunda suyu, お湯 isə isti suyu bildirir.","en":"水 usually means cold or room-temperature water; お湯 means hot water.","ru":"水 обычно обозначает холодную воду или воду комнатной температуры, а お湯 означает горячую воду."}},"消える":{"b":"消える (きえる)","p":"v","m":{"az":"sönmək, yox olmaq","en":"to go out, disappear","ru":"гаснуть, исчезать"},"n":{"az":"消えそうになる = az qala sönmək.","en":"消えそうになる = be about to go out.","ru":"消えそうになる = вот-вот погаснуть."}},"犬":{"b":"犬 (いぬ)","p":"n","m":{"az":"it","en":"dog","ru":"собака"}},"猫":{"b":"猫 (ねこ)","p":"n","m":{"az":"pişik","en":"cat","ru":"кошка"}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"知る":{"b":"知る (しる)","p":"v","m":{"az":"bilmək, tanımaq","en":"to know","ru":"знать"},"n":{"az":"Bilmirəm demək üçün 知りません deyilir. 知りませんでした = bilmirdilər (nəzakətli inkar, keçmiş).","en":"Negative: 知りません. 知りませんでした = did not know.","ru":"Отрицание: 知りません. 知りませんでした = не знали."}},"窓":{"b":"窓 (まど)","p":"n","m":{"az":"pəncərə","en":"window","ru":"окно"}},"立つ":{"b":"立つ (たつ)","p":"v","m":{"az":"dayanmaq, ayağa qalxmaq","en":"to stand","ru":"стоять, вставать"}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"答える":{"b":"答える (こたえる)","p":"v","m":{"az":"cavab vermək","en":"to answer","ru":"отвечать"}},"箱":{"b":"箱 (はこ)","p":"n","m":{"az":"qutu","en":"box","ru":"коробка"}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"背中":{"b":"背中 (せなか)","p":"n","m":{"az":"kürək","en":"back","ru":"спина"}},"胸":{"b":"胸 (むね)","p":"n","m":{"az":"sinə, köks","en":"chest, breast","ru":"грудь, грудная клетка"},"n":{"az":"胸がどきどきする = ürəyi həyəcanla döyünmək.","en":"胸がどきどきする = one's heart pounds with excitement or nervousness.","ru":"胸がどきどきする = сердце сильно бьётся от волнения."}},"自分":{"b":"自分 (じぶん)","p":"n","m":{"az":"öz, özü","en":"oneself","ru":"сам, свой"},"n":{"az":"自分の名前 = öz adı.","en":"自分の名前 = one's own name.","ru":"自分の名前 = своё имя."}},"落ちる":{"b":"落ちる (おちる)","p":"v","m":{"az":"düşmək, yıxılmaq","en":"to fall","ru":"падать"},"n":{"az":"落ちて来る = düşüb gəlmək (aşağı).","en":"落ちて来る = come falling down.","ru":"落ちて来る = упасть (сюда)."}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"話":{"b":"話 (はなし)","p":"n","m":{"az":"söhbət, hekayə","en":"conversation, story","ru":"разговор, история"}},"話す":{"b":"話す (はなす)","p":"v","m":{"az":"danışmaq; söhbət etmək","en":"to speak; to talk","ru":"говорить; разговаривать"},"n":{"az":"Dil を, həmsöhbət と ilə göstərilir: 日本語を話す, 友達と話す.","en":"A language takes を and a conversation partner takes と: 日本語を話す, 友達と話す.","ru":"Язык обозначается через を, собеседник через と: 日本語を話す, 友達と話す."}},"誕生":{"b":"誕生 (たんじょう)","p":"n","m":{"az":"doğulma, yaranma","en":"birth, creation","ru":"рождение, возникновение"},"n":{"az":"“Ad günü” üçün 誕生日 işlənir; 誕生する “doğulmaq, yaranmaq” deməkdir.","en":"“Birthday” is 誕生日; 誕生する means “be born” or “come into being.”","ru":"«День рождения» обозначается словом 誕生日; 誕生する означает «родиться, возникнуть»."}},"調べる":{"b":"調べる (しらべる)","p":"v","m":{"az":"araşdırmaq, yoxlamaq","en":"to investigate, to check, to look up","ru":"исследовать, проверять, искать сведения"},"n":{"az":"Söz və məlumat axtarışında da işlənir: 辞書で調べます.","en":"Also used to look up information: 辞書で調べます means to check in a dictionary.","ru":"Также используется для поиска сведений: 辞書で調べます - посмотреть в словаре."}},"赤い":{"b":"赤い (あかい)","p":"ai","m":{"az":"qırmızı","en":"red","ru":"красный"},"n":{"az":"赤く光る = qırmızı parlamaq (い → く: zərf).","en":"赤く光る = shine red (い → く: adverb).","ru":"赤く光る = светиться красным (い → く: наречие)."}},"迎える":{"b":"迎える (むかえる)","p":"v","m":{"az":"qarşılamaq, (gəlib) aparmaq","en":"to meet, to come for","ru":"встречать, приходить за"},"n":{"az":"迎えに来る = (kimisə) aparmağa gəlmək: feilin kökü + に + 来る = '...-mağa gəlmək'.","en":"迎えに来る = come to pick someone up: stem + に + 来る = 'come to do'.","ru":"迎えに来る = прийти за кем-то: основа + に + 来る = 'прийти, чтобы'."}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"遅い":{"b":"遅い (おそい)","p":"ai","m":{"az":"gec; yavaş","en":"late; slow","ru":"поздний; медленный"},"n":{"az":"い-sifətidir; vaxta görə «gec», sürətə görə «yavaş» deməkdir.","en":"An い-adjective meaning late for time and slow for speed.","ru":"い-прилагательное: для времени означает «поздний», для скорости «медленный»."}},"道":{"b":"道 (みち)","p":"n","m":{"az":"yol","en":"road, path","ru":"дорога"}},"金色":{"b":"金色 (きんいろ)","p":"n","m":{"az":"qızılı rəng","en":"gold color","ru":"золотой цвет"},"n":{"az":"金色に光る = qızılı rəngdə parlamaq.","en":"金色に光る = shine gold.","ru":"金色に光る = сиять золотом."}},"長い":{"b":"長い (ながい)","p":"ai","m":{"az":"uzun","en":"long","ru":"длинный; долгий"},"n":{"az":"İ-sifətdir və həm uzunluğu, həm də müddəti təsvir edir.","en":"An i-adjective describing both length and duration.","ru":"И-прилагательное, описывающее длину и длительность."}},"開ける":{"b":"開ける (あける)","p":"v","m":{"az":"açmaq","en":"to open","ru":"открывать"},"n":{"az":"開けると = açanda.","en":"開けると = when he opened.","ru":"開けると = когда открыл."}},"隣":{"b":"隣 (となり)","p":"n","m":{"az":"yan, qonşuluq","en":"next door, next to","ru":"соседство, рядом"},"n":{"az":"Nの隣 birbaşa N-in yanındakı yeri bildirir.","en":"Nの隣 refers to a place directly next to N.","ru":"Nの隣 обозначает место непосредственно рядом с N."}},"難しい":{"b":"難しい (むずかしい)","p":"ai","m":{"az":"çətin, mürəkkəb","en":"difficult, complicated","ru":"трудный, сложный"},"n":{"az":"い-sifətdir: 難しくない = çətin deyil.","en":"An i-adjective: 難しくない = not difficult.","ru":"Прилагательное на い: 難しくない = нетрудный."}},"電車":{"b":"電車 (でんしゃ)","p":"n","m":{"az":"elektrik qatarı","en":"electric train","ru":"электропоезд"}},"静か":{"b":"静か (しずか)","p":"an","m":{"az":"sakit, səssiz","en":"quiet","ru":"тихий"},"n":{"az":"静かになる = sakitləşmək (na-sifət + に + なる).","en":"静かになる = become quiet.","ru":"静かになる = стать тихим."}},"音":{"b":"音 (おと)","p":"n","m":{"az":"səs (əşya səsi)","en":"sound","ru":"звук"},"n":{"az":"音がする = səs gəlmək. İnsan səsi üçün 声.","en":"音がする = a sound is heard. Human voice: 声.","ru":"音がする = слышен звук. Голос человека – 声."}},"頭":{"b":"頭 (あたま)","p":"n","m":{"az":"baş","en":"head","ru":"голова"}},"顔":{"b":"顔 (かお)","p":"n","m":{"az":"üz, sifət","en":"face","ru":"лицо"}},"食べる":{"b":"食べる (たべる)","p":"v","m":{"az":"yemək","en":"to eat","ru":"есть"}},"駅":{"b":"駅 (えき)","p":"n","m":{"az":"stansiya","en":"station","ru":"станция"}},"黄色い":{"b":"黄色い (きいろい)","p":"ai","m":{"az":"sarı","en":"yellow","ru":"жёлтый"},"n":{"az":"İ-sifətdir; rəngin isim forması 黄色 olur.","en":"An i-adjective; the noun for the color is 黄色.","ru":"И-прилагательное; существительное для цвета: 黄色."}}}};